<https://example.org/openevidence/questions/q_acute_kidney_injury_treatment> a holon:ClinicalQuestionHolon ;
  holon:hasInteriorGraph <https://example.org/openevidence/questions/q_acute_kidney_injury_treatment-int> ;
  holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_acute_kidney_injury_treatment-bou> ;
