  holon:hasContextGraph <https://example.org/openevidence/questions/q_acute_kidney_injury_treatment-con> ;
  oe:questionText "What is the recommended first-line pharmacological treatment for Acute Kidney Injury?" ;
  oe:answerText "Furosemide" .

